import nodemailer from "nodemailer";
const couplePhoto=Buffer.from('','base64');
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validEmail=value=>typeof value==='string'&&value.length<=254&&/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(value);
export function messagingStatus(env=process.env){
 const required=['SMTP_HOST','SMTP_PORT','SMTP_USER','SMTP_PASSWORD','EMAIL_FROM','PUBLIC_SITE_URL'];const missing=required.filter(k=>!env[k]);
 return {enabled:env.EMAIL_ENABLED==='true'&&missing.length===0,missing,switchedOn:env.EMAIL_ENABLED==='true',provider:'smtp'};
}
export async function notifyDecision(guest,{env=process.env,createTransport=nodemailer.createTransport}={}){
 if(!validEmail(guest.email))return {status:'no_email',detail:'This RSVP has no valid email address.'};
 if(guest.emailConsent!==true)return {status:'no_consent',detail:'The guest has not opted in to email RSVP updates.'};
 if(!['approved','declined'].includes(guest.status))return {status:'failed',detail:'Invalid RSVP decision.'};
 if(!messagingStatus(env).enabled)return {status:'not_configured',detail:'Email sending is not connected. The RSVP decision is saved.'};
 let origin;try{const u=new URL(env.PUBLIC_SITE_URL);if(u.protocol!=='https:')throw Error();origin=u.origin}catch{return {status:'not_configured',detail:'PUBLIC_SITE_URL must be the HTTPS wedding website address.'}}
 if(/[\r\n]/.test(env.EMAIL_FROM)||!env.EMAIL_FROM.includes('@'))return {status:'not_configured',detail:'Check the verified sender address.'};
 if(env.EMAIL_REPLY_TO&&!validEmail(env.EMAIL_REPLY_TO))return {status:'not_configured',detail:'Check the reply-to address.'};
 const name=String(guest.name||'Guest').trim().replace(/\s+/g,' '),link=origin+'/?guest='+encodeURIComponent(guest.id)+'#status';
 const date=new Date(guest.weddingDate+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
 const text=guest.status==='approved'?`Hello ${name},\n\nYour RSVP for Vimbai and Clarence’s wedding on ${date} at ${guest.weddingTime||'13:30'} (Harare time) has been approved.\n\nWe can’t wait to celebrate with you! Open your personal link to enter the guest lounge and view the programme and directions:\n${link}\n\nPlease keep this link private.\n\nWith love,\nVimbai & Clarence`:`Hello ${name},\n\nThank you for responding to Vimbai and Clarence’s wedding invitation. We are unable to confirm your attendance. We appreciate your understanding and send our warm wishes.\n\nVimbai & Clarence`;
 const approved=guest.status==='approved';
 const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"></head><body style="margin:0;padding:0;background:#f4f0e6;color:#314535"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f4f0e6"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:#fffdf6;border:1px solid #e4dac0"><tr><td align="center" style="background:#344b37;padding:26px 20px;color:#f4e1a8;font-family:Georgia,serif;font-size:30px">Vimbai <span style="color:#d5b66e">&amp;</span> Clarence<div style="font:11px Arial,sans-serif;letter-spacing:3px;color:#f7f3e9;margin-top:12px">A CELEBRATION OF LOVE</div></td></tr><tr><td><img src="cid:couple@zurielegance.co.za" width="600" alt="Vimbai and Clarence" style="display:block;width:100%;height:auto;border:0"></td></tr><tr><td style="padding:30px 26px;font:16px/1.7 Arial,sans-serif"><div style="font:italic 32px/1.2 Georgia,serif;color:#8c7034;margin:0 0 22px">${approved?'We saved you a seat':'Your RSVP update'}</div><p style="margin:0 0 18px">Hello <strong>${escapeHtml(name)}</strong>,</p>${approved?`<p>Your RSVP has been <strong style="color:#344b37">approved</strong>. We can’t wait to celebrate with you!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f0eddf;border-left:4px solid #c7a357"><tr><td style="padding:18px;font:16px/1.6 Georgia,serif"><strong>${escapeHtml(date)}</strong><br>${escapeHtml(guest.weddingTime||'13:30')} · Harare time</td></tr></table><p>Everything you need for our special day is waiting in your personal guest lounge.</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td bgcolor="#344b37" style="border-radius:6px"><a href="${escapeHtml(link)}" style="display:inline-block;padding:15px 25px;color:#fffdf6;text-decoration:none;font:bold 16px Arial,sans-serif">Enter the guest lounge &rarr;</a></td></tr></table><p style="font-size:12px;color:#6b705f;margin-top:20px">This invitation link is personal to you. Please keep it private.<br>If the button doesn’t open, <a href="${escapeHtml(link)}" style="color:#536647">open your lounge here</a>.</p>`:`<p>Thank you for responding to our wedding invitation. We are unable to confirm your attendance. We appreciate your understanding and send our warm wishes.</p>`}<p style="margin:26px 0 0">With love,<br><span style="font:italic 24px Georgia,serif;color:#8c7034">Vimbai &amp; Clarence</span></p></td></tr><tr><td align="center" style="padding:18px;background:#344b37;color:#f4e1a8;font:11px Arial,sans-serif;letter-spacing:2px">TOGETHER, FOR A BRIGHTER TOMORROW</td></tr></table></td></tr></table></body></html>`;
 const port=Number(env.SMTP_PORT);
 if(![465,587].includes(port)||!validEmail(env.SMTP_USER)||!validEmail(env.EMAIL_FROM))return {status:'not_configured',detail:'Check SMTP port, username and sender address.'};
 const transport=createTransport({host:env.SMTP_HOST,port,secure:port===465,requireTLS:true,auth:{user:env.SMTP_USER,pass:env.SMTP_PASSWORD},connectionTimeout:15000,greetingTimeout:15000,socketTimeout:30000,logger:false,debug:false,disableFileAccess:true,disableUrlAccess:true});
 try{
 const result=await transport.sendMail({from:{name:'Vimbai & Clarence',address:env.EMAIL_FROM},to:guest.email,subject:guest.status==='approved'?'Your RSVP is approved — Vimbai & Clarence':'Your RSVP update — Vimbai & Clarence',text,html,attachments:[{filename:'vimbai-and-clarence.jpg',content:couplePhoto,contentType:'image/jpeg',cid:'couple@zurielegance.co.za',contentDisposition:'inline'}],...(env.EMAIL_REPLY_TO?{replyTo:env.EMAIL_REPLY_TO}:{}),messageId:'<rsvp-'+guest.emailNotification.attemptId+'@'+env.EMAIL_FROM.split('@')[1]+'>'});
 if(!result.accepted?.length)return {status:'failed',detail:'Mail server did not accept the recipient.'};
 return {status:'submitted',sid:result.messageId,detail:'Accepted by the mail server; inbox delivery is not confirmed.'};
 }catch(error){
 if(['EAUTH','EENVELOPE','EDNS','ECONNECTION','ETLS'].includes(error.code)||Number(error.responseCode)>=400)return {status:'failed',detail:'Mail server rejected the connection or message. Check SMTP settings and credentials.'};
 return {status:'unknown',detail:'Email sending result uncertain. Check mail delivery logs before retrying to avoid duplicate emails.'};
 }finally{transport.close?.()}
}
